pub fn render(source: &str, width: usize) -> Vec<Block> {
    let mut state = State::default();
    let parser = Parser::new_ext(
        source,
        Options::ENABLE_TABLES | Options::ENABLE_STRIKETHROUGH | Options::ENABLE_TASKLISTS,
    );

    for event in parser {
        state.event(event, width);
    }
    state.flush();
    state.blocks
}

#[derive(Default)]
struct State {
    blocks: Vec<Block>,
    spans: Vec<Span>,
    indent: usize,
    lists: Vec<List>,
    quote: usize,
    bold: usize,
    italic: usize,
    strike: usize,
    code: bool,
    link: Option<String>,
    cells: Vec<String>,
    in_table: bool,
    heading: bool,
}

enum List {
    Bullet,
    Ordered(u64),
}

    }

    /// One empty line, never two in a row.
    fn blank(&mut self) {
        if self
            .blocks
            .last()
            .is_some_and(|block| block.spans.is_empty())
        {
            return;
        }
        self.blocks.push(Block {
            indent: 0,
            spans: Vec::new(),
            code: false,
        });
